.clearfix:after {content:"";display:block;clear:both;}



#Navbar1, #Attribution1, h1 p, .feed-links, a.home-link {
    display: none;
}

html{
    box-sizing:border-box;
    -webkit-text-size-adjust:100%;
    -ms-text-size-adjust:100%
}
*,*:before,*:after{
    box-sizing:inherit;
    margin:0;
    padding:0;
    word-wrap:break-word
}
h1,h2,h3,h4,h5,h6,h7,h8,h10{
    font-weight:400
}
table{
    border-collapse:collapse;
    border-spacing:0
}
img,fieldset{
    border:0
}
abbr,acronym{
    text-decoration:none
}
code{
    font-family:Consolas,"Courier New",monospace;
    background:#eee;
    padding:0 5px;
    border-radius:2px;
    border:1px solid #E1DADA
}
sub,sup{
    line-height:.5em
}
.post-body img,iframe,video,embed,object{
    display:block;
    width:100%;
    height:auto
}

body{
    font-family:Georgia,"Times New Roman",Times,serif;
    font-size:16px;
    line-height:27px;
    font-weight:400;
    color:#111;
    background-image: linear-gradient(to right, #ffffff 35%, #eef4dc 0);
}
.cumo-svg{
    background: #c0c0c0;
    display: block;
    overflow: hidden;
    position: absolute;
    z-index: 9;
}
.circulo{
    fill:none;
    stroke:#fff;
    stroke-width:3;
    stroke-miterlimit:10;
}

.cumo-bio{

	background: #000;
	width:100%;
    margin-bottom: 5em;
    position: relative;
}
a{
    text-decoration:none;
    color:#2e3ca1
}
p a{
    text-decoration:underline
}

#blog-wrapper{
    width:1024px;
    margin:0 auto
}
#content-wrapper{
    width:100%;
    height:100%;
    overflow:hidden
}
#main{
    padding:25px 25px 25px 20px;
    max-width: 1200px;
    height:100%;
}
aside{
    width:32%;
    height:100%;
    padding:25px;
}
footer{
    width:100%;
    clear:both;
background: #fff;
    padding:20px
}
header{
    padding:30px 20px;
    margin-top:25px
}
h1.title{
    font-size:40px;
    font-weight:700;
    line-height:1.5em
}
.description span{
    color:#727272
}
.date-header span{
    font-size:15px;
    color:#696969
}
.post-title{
    font-size:28px;
    line-height:1.25em
}
.post-body{
    margin:15px auto
}
.post-body h1{
    font-size:33px;
    margin:0 auto 18px
}
.post-body h2{
    font-size:28px;
    margin:0 auto 14px
}
.post-body h3{
    font-size:24px;
    margin:0 auto 10px
}
.post-body h4{
    font-size:20px;
    margin:0 auto 8px
}
.post-body h5{
    font-size:18px;
    margin:0 auto 8px
}
.post-body h6{
    font-size:16px;
    margin:0 auto 6px;
    font-weight:700
}
.post-body a{
    text-decoration:underline
}
.post-body a:hover{
    text-decoration:none
}
.post-body ul,.post-body ol{
    margin:0 0 0 25px
}
.post-body ul{
    list-style-type:square
}
.post-body ul li:not(:last-child),.post-body ol li:not(:last-child){
    margin-bottom:5px
}
.post-body blockquote{
    border-left:7px solid #d2d2d2;
    padding-left:20px;
    font-style:italic;
    margin:0 15px;
    color:#626262
}
.post-outer{
    margin-bottom:25px
}
.post-footer{
    border-bottom:1px solid #ddd
}
.post-footer-line-1,.post-footer-line-2,.author-profile{
    margin-bottom:10px
}
.post-labels,.post-author,.post-timestamp{
    font-weight:700
}
.post-labels a,.post-author a,.post-timestamp a{
    font-weight:400
}
.jump-link{
    float:right
}
.reactions-iframe{
    padding-top:8px
}
.blog-feeds,.post-feeds{
    margin-bottom:25px
}
#comments{
    margin-top:25px
}
#comments h4{
    font-size:20px;
    font-weight:700
}
#comment-post-message{
    font-size:16px!important;
    font-weight:normal!important
}
#sidebar{
    display:none;
}
.status-msg-wrap{
    font-size:110%;
    width:100%;
    margin:35px auto 10px;
    position:relative;
    font-size:15px
}
.status-msg-border{
    border:1px solid #868686;
    filter:alpha(opacity=40);
    opacity:.4;
    width:100%;
    position:relative
}
.status-msg-bg{
    background-color:#eee;
    opacity:.8;
    filter:alpha(opacity=30);
    width:100%;
    position:relative;
    z-index:1
}
.status-msg-body{
    color:#444;
    text-align:center;
    padding:.3em 10px;
    width:100%;
    position:absolute;
    z-index:4
}
.status-msg-hidden{
    visibility:hidden;
    padding:.3em 0
}
.status-msg-wrap a{
    padding-left:.4em;
    text-decoration:underline
}
p.note,div.note{
    background:#ddd;
    padding:15px 20px
}
p.alert,div.alert{
    background:#f6f697;
    padding:15px 20px
}
p.alert a:hover,div.alert a:hover,p.note a:hover,div.note a:hover{
    text-decoration:none
}
p.note a,p.alert a{
    color:#0a54ca
}
pre{
    background-color:#eee;
    width:100%;
    white-space:pre;
    word-wrap:normal;
    margin-bottom:0;
    line-height:22px;
    overflow:auto;
    clear:both
}
pre code{
    display:block;
    padding:0 15px 20px;
    border-radius:3px;
    border:none;
    font-size:15px;
    font-family:Consolas,"Courier New",monospace!important
}
img.frame{
    padding:.8em;
    background:#eee;
    border:1px solid #ddd
}
img.thin_frame{
    padding:5px;
    background:#eee;
    border:1px solid #ddd
}

footer{
backgroud: #c1c1c1;
}

.cumo-footer{
}

.section{
 	margin: 0px;
}

#HTML2{
}

@media screen and (max-width:1040px){
    .content-table,.content-row,.column{
        display:block
    }
    #blog-wrapper{
        width:100%
    }
    #main{
        padding:0 25px;
        width:100%;
        margin:25px auto 30px;
        display:block
    }
    .Blog{
    }

    aside{
        float:none;
        clear:both;
        padding:0;
        width:auto;
        margin:0 25px;
        position:relative;
        border:none
    }
    .post-body{
        line-height:30px
    }
}

::-webkit-scrollbar {
    background-color: #transparent;
    height: 7px;
    width: 10px;
}


::-webkit-scrollbar-button:start:decrement,
::-webkit-scrollbar-button:end:increment  {
  display: none;
}

::-webkit-scrollbar-track-piece  {
  background-color: #transparent;
}

::-webkit-scrollbar-thumb:vertical {
  background-color: #eef4dc;
}


::selection {
    background: #ffffff;
    color: #556B2F;
}

@media screen and (max-width:900px){
    .post-body{
        line-height:29px
    }
}
@media screen and (max-width:800px){
    .post-body{
        line-height:28px
    }
}
@media screen and (max-width:650px){
    .post-body{
        line-height:27px
    }
}
@media screen and (max-width:500px){
    .post-body{
        line-height:26px
    }
    input[type="text"],input[type="number"],input[type="url"],input[type="tel"],input[type="email"],input[type="password"],select,textarea{
        width:100%
    }
    img[align="left"],img[align="right"]{
        display:block;
        margin-right:auto;
        margin-left:auto;
        text-align:center;
        float:none;
        clear:both
    }
}
@media screen and (max-width:350px){
    .post-body{
        line-height:25px
    }
}



/* --------- INSTAFEED ----------- */
#instafeed {
width: 100%;
display: block;
margin: 0 auto;
padding: 0px;
line-height: 0px;
text-align: center;
vertical-align: baseline;
}
#instafeed img {
width: 100%;
height: auto;
}
#instafeed .squarethumb {
background-position: 50% !important;
background-size: cover !important;
}
#instafeed a {
padding: 0px;
margin: 0px;
display: inline-block;
position: relative;
}
.instathumb {
    width: 16.6%; /* Largura das fotos */
    display: inline-block;
}
.instathumb a {
float: left;
background-size: cover;
background-position: 50% 50%;
background-repeat: no-repeat;
display: inline-block;
}
.fcdw {
width: 100%;
height: 100%;
margin-top: -100%;
opacity: 0;
text-align: center;
position: absolute;
background-size: 30px;
font-family: 'Lato', sans-serif; /* Fonte dos números de likes e comentário*/
font-weight: 400;
font-size: 11px;
letter-spacing: 1px;
color: #ffffff; /*Cor da fonte*/
line-height: 1.5;
-webkit-font-smoothing: antialiased;
}
.fcdw:hover {
opacity: 1;
}
.fcdw:hover:after {
content: '';
top: 0;
left: 0;
width: 100%;
height: 100%;
position: absolute;
display: block;
background: #2E2E2E; /* Cor ao passar o mouse*/
-ms-filter: "progid:DXImageTransform.Microsoft.Alpha(Opacity=90)";
filter: alpha(opacity=90);
opacity: 0.9;
z-index: 1;
}
.fcdw i {
color: #ffffff; /* Cor dos ícones*/
font-size: 10px;
margin: 0 4px 0 0;
}
.fcdo {
display: table;
vertical-align: middle;
height: 100%;
width: 100%;
}
.fcdi {
display: table-cell;
vertical-align: middle;
height: 100%;
width: 100%;
z-index: 5;
position: relative;
}



.entry-summary { 
    overflow: hidden;
    width: 100%;
    box-sizing: border-box;
    padding: 5px
}

.entry-summary img.post-thumbnail {
    float: left;
    width: 250px;
    height: auto;
    padding: 0 10px 0 0;
    margin: 10px 0 0 0
}

.entry-summary .snippet {
    font-size: 16px;
    padding: 0;
    margin: 0;
    text-align: justify;
    -webkit-margin-before: 1em;
    -webkit-margin-after: 1em;
    -webkit-margin-start: 0;
    -webkit-margin-end: 0;
}

@media (max-width:600px) {
    .entry-summary .snippet {
        float: none;
        text-align: center
    }
    .entry-summary img.post-thumbnail {
        width: 100%;
        padding: 0
    }
}

